import React, { useState, useEffect } from "react";
import axios from "axios";
import QuestionCard from "./component/QuestionCard";
import "./App.css";

function App() {
  const [masterQuestionList, setMasterQuestionList] = useState([]);
  const [isDataLoading, setIsDataLoading] = useState(true);
  const [isPrivacyModeActive, setIsPrivacyModeActive] = useState(false);

  const generateEmptyForm = () => Array(5).fill(null).map(() => ({ 
    selectedQuestion: "", 
    answerText: "", 
    confirmedAnswerText: "" 
  }));

  const [formEntries, setFormEntries] = useState(generateEmptyForm());

  useEffect(() => {
    axios.get("http://localhost:3001/questions")
      .then((res) => {
        setMasterQuestionList(res.data);
        setIsDataLoading(false);
      })
      .catch((err) => {
        console.error("Fetch Error:", err);
        setIsDataLoading(false);
      });
  }, []);

  const handleEntryUpdate = (index, field, value) => {
    const updated = [...formEntries];
    updated[index][field] = value;
    setFormEntries(updated);
  };

  const submitSecurityForm = async () => {
    const isComplete = formEntries.every(e => e.selectedQuestion && e.answerText && e.confirmedAnswerText);
    const isMatched = formEntries.every(e => e.answerText === e.confirmedAnswerText);

    if (!isComplete) return alert("Please fill all 5 slots.");
    if (!isMatched) return alert("Validation Error: Answers do not match.");

    try {
      await axios.post("http://localhost:3001/responses", { data: formEntries });
      alert("Security setup complete.");
      setFormEntries(generateEmptyForm());
    } catch (err) {
      alert("Submission failed.");
    }
  };

  const getAvailableOptions = (currentIndex) => {
    const pickedInOtherSlots = formEntries
      .filter((_, idx) => idx !== currentIndex)
      .map(entry => entry.selectedQuestion);

    return masterQuestionList.filter(item => !pickedInOtherSlots.includes(item.question));
  };

  if (isDataLoading) return <div className="app-container">Connecting to server...</div>;

  return (
    <div className="app-container">
      <div className="privacy-toggle">
        <label>
          <input 
            type="checkbox" 
            checked={isPrivacyModeActive} 
            onChange={() => setIsPrivacyModeActive(!isPrivacyModeActive)} 
          />
          Hide Answers
        </label>
      </div>

      <h1 className="header-text">Security Questions</h1>

      <div className="form-card">
        {formEntries.map((entry, index) => (
          <QuestionCard
            key={index}
            index={index}
            formData={entry}
            availableOptions={getAvailableOptions(index)}
            maskAnswers={isPrivacyModeActive} 
            onUpdate={handleEntryUpdate}
          />
        ))}
        <button className="btn-submit" onClick={submitSecurityForm}>
          Save All Responses
        </button>
      </div>
    </div>
  );
}

export default App;
